package com.tekwatt.analytics.service;
import com.tekwatt.analytics.dto.*;import com.tekwatt.analytics.entity.AnalyticsEvent;import com.tekwatt.analytics.repository.AnalyticsEventRepository;import java.math.BigDecimal;import java.sql.Date;import java.time.*;import java.util.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service @Transactional public class AnalyticsService {private final AnalyticsEventRepository repository;public AnalyticsService(AnalyticsEventRepository repository){this.repository=repository;}public UUID record(AnalyticsEventRequest r){if(repository.existsByExternalEventId(r.externalEventId()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Analytics event already recorded");return repository.save(new AnalyticsEvent(r.externalEventId(),r.tenantId(),r.chargerId(),r.sessionId(),r.energyKwh(),r.revenue(),r.currency(),r.durationSeconds(),r.occurredAt())).getId();}@Transactional(readOnly=true)public AnalyticsOverview overview(UUID tenantId,Instant from,Instant to){validate(from,to);Object[] row=unwrap(repository.overview(tenantId,from,to));return new AnalyticsOverview(tenantId,from,to,longValue(row[0]),decimal(row[1]),decimal(row[2]),longValue(row[3]),longValue(row[4]));}@Transactional(readOnly=true)public List<DailyAnalytics> daily(UUID tenantId,LocalDate from,LocalDate to){if(from.isAfter(to))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"from must not be after to");Instant start=from.atStartOfDay(ZoneOffset.UTC).toInstant();Instant end=to.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant();return repository.daily(tenantId,start,end).stream().map(r->new DailyAnalytics(((Date)r[0]).toLocalDate(),longValue(r[1]),decimal(r[2]),decimal(r[3]),longValue(r[4]),longValue(r[5]))).toList();}private void validate(Instant from,Instant to){if(!from.isBefore(to))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"from must be before to");}private Object[] unwrap(Object[] value){return value.length==1&&value[0] instanceof Object[] nested?nested:value;}private long longValue(Object v){return v==null?0:((Number)v).longValue();}private BigDecimal decimal(Object v){return v==null?BigDecimal.ZERO:new BigDecimal(v.toString());}}
